// npm run export -- THE WORLD AS A GLB FOR BLENDER (r60).
//
// *"Is there any way to get this scene into a Blender file? I'd love to get a visual read, do some curating of where
// buildings go and build more onto it."* The world is generated by code at load, so there is no file to hand over --
// until this: it boots the REAL module headless (the same page `npm run sim` builds), lets `init()` build every
// district, and writes what is in the scene out as glTF binary, which Blender imports with File > Import > glTF.
//
//   exports/rollergirl_world.glb       the picture: one object per district chunk, baked into world space, grouped
//                                      under hub / slice / orbital / shores / city / backdrop, with vertex colours,
//                                      the generated textures (paving, sandstone, plaster ... and their normal maps)
//                                      embedded as PNG, and every grind rail as an EDGE polyline under `rails`
//   exports/rollergirl_collision.glb   what she actually collides with, in the handoff's own naming: `deck_` floors
//                                      (one mesh per district) and every solid as a `bld_` box -- the same convention
//                                      `levelIngest` reads back, so a curated copy can come home through it
//
// WHAT IS NOT IN IT, AND WHY: her (draco wants a Worker headless), his weirdport kit and BKG0-3 (already his Blender
// files -- the plain stand-in boxes are exported where the kit would sit), the canvas-painted sign atlas (no 2D
// canvas headless, so signs come out as bare quads), particles, glow cards and the sky. The detail shader is a
// runtime effect and does not survive into a file either.
//
// Units are metres, +Y up (Blender's importer converts to Z up). Run it again after any change to the world.

import fs from 'fs'; import os from 'os'; import path from 'path';
import { pathToFileURL } from 'url';

if (!fs.existsSync('node_modules/three/package.json')) {
  fs.mkdirSync('node_modules/three', { recursive: true });
  fs.writeFileSync('node_modules/three/package.json', JSON.stringify({
    name: 'three', version: '0.180.0-vendored', type: 'module', main: 'index.js', exports: { '.': './index.js' } }));
  fs.writeFileSync('node_modules/three/index.js', "export * from '../../vendor/three.module.min.js';\n");
}
const TMP = path.join(os.tmpdir(), 'rollergirl-sim');
fs.mkdirSync(TMP, { recursive: true });
const ROOT = pathToFileURL(process.cwd() + '/').href;
fs.writeFileSync(path.join(TMP, 'three-shim.mjs'), `
export * from '${ROOT}vendor/three.module.min.js';
import * as T from '${ROOT}vendor/three.module.min.js';
class FakeTarget { constructor(w,h,o){ this.width=w; this.height=h; this.texture=new T.Texture(); } setSize(){} dispose(){} }
export { FakeTarget as WebGLRenderTarget };
class FakeRenderer { constructor(){ this.domElement = globalThis.document.createElement('canvas');
  this.shadowMap={enabled:false,type:0}; this.info={autoReset:true,render:{calls:0,triangles:0},reset(){}};
  this.capabilities={isWebGL2:true,getMaxAnisotropy:()=>1,precision:'highp'};
  this.outputColorSpace=''; this.toneMapping=0; this.toneMappingExposure=1; }
  setSize(){} setPixelRatio(){} setClearColor(){} setRenderTarget(){} clear(){} render(){} dispose(){}
  compile(){} getContext(){ return {getParameter:()=>0}; } getDrawingBufferSize(v){ return v.set(1280,720); } initTexture(){} }
export { FakeRenderer as WebGLRenderer };
class FakePMREM { constructor(){} fromEquirectangular(){ return { texture: new T.Texture() }; } compileEquirectangularShader(){} dispose(){} }
export { FakePMREM as PMREMGenerator };
`);
const boot = fs.readFileSync('tools/boot.mjs', 'utf8');
const stubs = boot.slice(boot.indexOf('// STUBS:START'), boot.indexOf('// STUBS:END'));
(0, eval)(stubs);
// r64: the export is of the world this file builds, not of his zones. r66: `npm run export kit` is the ramp kit instead.
const KITMODE = process.argv[2] === 'kit';
globalThis.localStorage.setItem('rg.world', KITMODE ? '2' : '0');
if (KITMODE) globalThis.__kitKeep = 1;     // each piece keeps a copy of its own triangles to be written out

const html = fs.readFileSync('index.html', 'utf8');
let src = html.match(/<script type="module">([\s\S]*?)<\/script>/)[1];
