      sweep_deg: S.sweep && Math.round(S.sweep * 180 / Math.PI), deck: K.deck, footprint_w_by_u: [+(pc.wid || 0).toFixed(2), +(pc.len || 0).toFixed(2)], top: pc.h != null ? +(+pc.h).toFixed(2) : undefined,
