      out2: pc.out2 ? { at: [+pc.out2.w.toFixed(3), +pc.out2.y.toFixed(3), +pc.out2.u.toFixed(3)], yaw_deg: +(pc.out2.dyaw * 180 / Math.PI).toFixed(2) } : undefined,
